// src/utils/createNode.ts
import type { FlowsheetNode } from "@/types/units";
import { allUnits } from "@/data/units";

export function createNodeFromUnit(
  unitId: string,
  position: { x: number; y: number }
): FlowsheetNode | null {
  const unit = allUnits.find((u) => u.id === unitId);
  if (!unit) return null;

  const id = `${unit.id}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  return {
    id,
    type: "processNode",
    position,
    data: {
      unitId: unit.id,
      label: unit.name,
      metal: unit.metal,
      icon: unit.icon,
      parameters: {
        recovery: unit.defaultParameters.recovery,
        split_ratio: unit.defaultParameters.split_ratio,
      },
    },
    style: {
      borderRadius: 8,
      padding: 8,
      borderWidth: 1,
      borderColor: "#CBD5F5",
      backgroundColor: "#FFFFFF",
      fontSize: 11,
    },
  };
}
